import json, math, sys

def number(value, minimum=0):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or value < minimum or value > sys.float_info.max or not math.isfinite(value):
        raise ValueError('invalid finite number')
    return value

def analyze(data):
    if not isinstance(data, dict) or set(data) != {'policy', 'windows'}:
        raise ValueError('schema')
    p = data['policy']
    if not isinstance(p, dict) or set(p) != {'window_seconds','min_windows','min_success_ratio','max_p95_ms','max_error_ratio','max_cpu','max_fd_ratio','max_queue'}:
        raise ValueError('policy schema')
    span = number(p['window_seconds'], 1)
    count = p['min_windows']
    if type(count) is not int or count < 2:
        raise ValueError('min_windows')
    for key in ['min_success_ratio','max_error_ratio','max_cpu','max_fd_ratio']:
        if number(p[key]) > 1: raise ValueError('ratio')
    for key in ['max_p95_ms','max_queue']: number(p[key])
    windows = data['windows']
    if not isinstance(windows, list): raise ValueError('windows')
    by_rate, seen = {}, set()
    for w in windows:
        if not isinstance(w, dict) or set(w) != {'rate','index','seconds','requests','cpu','fd_ratio','queue'}:
            raise ValueError('window schema')
        rate = number(w['rate'], 1)
        index = w['index']
        if type(index) is not int or index < 0: raise ValueError('index')
        if (rate,index) in seen: raise ValueError('duplicate window')
        seen.add((rate,index))
        if number(w['seconds'], 1) != span: raise ValueError('window duration')
        for key in ['cpu','fd_ratio']:
            if number(w[key]) > 1: raise ValueError('resource ratio')
        number(w['queue'])
        records = w['requests']
        if not isinstance(records,list) or not records: raise ValueError('empty window')
        latencies, successes = [], 0
        for rec in records:
            if not isinstance(rec,dict) or set(rec) != {'status','latency_ms'}: raise ValueError('request schema')
            status = rec['status']
            if type(status) is not int or not 100 <= status <= 599: raise ValueError('status')
            latency = number(rec['latency_ms'])
            latencies.append(latency)
            successes += 200 <= status < 400
        latencies.sort()
        p95 = latencies[math.ceil(.95 * len(latencies))-1]
        throughput = successes/span
        error_ratio = (len(records)-successes)/len(records)
        reasons = []
        if throughput < rate * p['min_success_ratio']: reasons.append('throughput')
        if p95 > p['max_p95_ms']: reasons.append('latency')
        if error_ratio > p['max_error_ratio']: reasons.append('errors')
        for key, limit in [('fd_ratio','max_fd_ratio'),('queue','max_queue')]:
            if w[key] > p[limit]: reasons.append(key)
        by_rate.setdefault(rate,[]).append({'index':index,'throughput':throughput,'p95_ms':p95,'error_ratio':error_ratio,'reasons':reasons})
    levels = []
    for rate, rows in sorted(by_rate.items()):
        rows.sort(key=lambda x:x['index'])
        contiguous = [r['index'] for r in rows] == list(range(len(rows)))
        eligible = contiguous and len(rows) >= count and all(not r['reasons'] for r in rows)
        levels.append({'rate':rate,'eligible':eligible,'complete':contiguous and len(rows)>=count,'windows':rows})
    # A failed lower tested level invalidates every higher result: a disconnected
    # high-rate island is evidence for another run, not a capacity certificate.
    selected = None
    for level in levels:
        if not level['eligible']: break
        selected = level['rate']
    return {'sustainable_rate':selected,'levels':levels,'scope':'offline supplied measurements; not a production benchmark'}

def main():
    if len(sys.argv) != 2: raise ValueError('usage: capacity.py input.json')
    def reject(value): raise ValueError('non-finite JSON')
    def unique(pairs):
        result={}
        for key,value in pairs:
            if key in result: raise ValueError('duplicate JSON key')
            result[key]=value
        return result
    with open(sys.argv[1],encoding='utf8') as f:
        data=json.load(f,parse_constant=reject,object_pairs_hook=unique)
    print(json.dumps(analyze(data),ensure_ascii=False,allow_nan=False))

if __name__=='__main__':
    try: main()
    except (ValueError,TypeError,KeyError,OSError) as error:
        print(str(error),file=sys.stderr);sys.exit(2)

